INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('0aa785f7620f17854525','Neuro Amedex 2025.pdf','130','Neurology','Joan, 60 years of age, is in the Emergency
bapartment with complaint of acute onset of a
spinning sensation at home followed by severe
nausea and vomiting. She has never had a
similar episode. She also denies any recent
history of upper respiratory tract infections. On
examination, she has a blood pressure of
164/104 mmHg, heart rate of 103 bpm and
regular, respiratory rate of 17 breaths per
minute and temperature of 37.0°C. Remarkable
exam findings include nystagmus, decreased
hearing of the left ear, left-sided Horner
syndrome, ipsilateral sensory loss of the face
and contralateral sensory deficits of the limbs.
No motor dysfunction of the limbs is noted but
ataxia is present. Based on the clinical picture,
a diagnosis of stroke is made. Which one of the
following arteries is most likely to be occluded?','{"A":"Anterior communicating artery.","B":"Posterior cerebral artery.","C":"Anterior cerebral artery.","D":"Posterior inferior cerebellar artery.","E":"Internal carotid artery."}',NULL,NULL,'{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Neuro Amedex 2025.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-cb5af1022aca","duplicate_sources":[{"record_id":"0aa785f7620f17854525","record_type":"text_mcq","source_file":"Neuro Amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Neuro Amedex 2025.pdf","source_page":130,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"0aa785f7620f17854525","source_file":"Neuro Amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Neuro Amedex 2025.pdf","source_year":2025,"source_page":130,"source_qid":null,"domain_hint":"Neurology","stem":"Joan, 60 years of age, is in the Emergency\nbapartment with complaint of acute onset of a\nspinning sensation at home followed by severe\nnausea and vomiting. She has never had a\nsimilar episode. She also denies any recent\nhistory of upper respiratory tract infections. On\nexamination, she has a blood pressure of\n164/104 mmHg, heart rate of 103 bpm and\nregular, respiratory rate of 17 breaths per\nminute and temperature of 37.0°C. Remarkable\nexam findings include nystagmus, decreased\nhearing of the left ear, left-sided Horner\nsyndrome, ipsilateral sensory loss of the face\nand contralateral sensory deficits of the limbs.\nNo motor dysfunction of the limbs is noted but\nataxia is present. Based on the clinical picture,\na diagnosis of stroke is made. Which one of the\nfollowing arteries is most likely to be occluded?","options":{"A":"Anterior communi